// src/pages/CesiumViewer.jsx
import React, { useEffect, useRef } from "react";
import { useParams } from "react-router-dom";

/*
  This component uses the Cesium CDN loaded in public/index.html.
  Make sure public/index.html includes:
    <link href="https://cdn.jsdelivr.net/npm/cesium@1.109/Build/Cesium/Widgets/widgets.css" rel="stylesheet" />
    <script src="https://cdn.jsdelivr.net/npm/cesium@1.109/Build/Cesium/Cesium.js"></script>

  Then Cesium is available as window.Cesium and we can use window.Cesium.Viewer etc.
*/

export default function CesiumViewer() {
  const { kmlId } = useParams();
  const containerRef = useRef(null);

  useEffect(() => {
    // Wait for Cesium global to be available
    if (typeof window === "undefined" || !window.Cesium) {
      console.error("Cesium not loaded. Did you add the CDN script to public/index.html?");
      if (containerRef.current) {
        containerRef.current.innerHTML =
          "Cesium not loaded. Check public/index.html for Cesium CDN <script>.";
      }
      return;
    }

    if (!kmlId) {
      if (containerRef.current) {
        containerRef.current.innerHTML =
          "Missing KML id. Use /viewer/:kmlId";
      }
      return;
    }

    // Use the global Cesium object
    const Cesium = window.Cesium;

    // Create the viewer
    const viewer = new Cesium.Viewer(containerRef.current, {
      timeline: false,
      animation: false,
      // you can tweak these viewer options as needed
    });

    // Compose backend kml URL (adjust backend host if not localhost:5000)
    const backend = process.env.REACT_APP_API_URL || "http://localhost:5000";
    const kmlUrl = `${backend}/api/kml/public/${encodeURIComponent(kmlId)}`;

    // Load the KML - KmlDataSource is available on window.Cesium
    Cesium.KmlDataSource.load(kmlUrl, { clampToGround: true })
      .then((dataSource) => {
        viewer.dataSources.add(dataSource);
        viewer.zoomTo(dataSource);
      })
      .catch((err) => {
        console.error("Failed to load KML:", err);
        if (containerRef.current) {
          containerRef.current.innerHTML =
            "Failed to load KML. Check console for details.";
        }
      });

    // cleanup
    return () => {
      try {
        viewer.destroy();
      } catch (e) {
        /* ignore cleanup errors */
      }
    };
  }, [kmlId]);

  return <div ref={containerRef} style={{ width: "100%", height: "100vh" }} />;
}
